217	/// Proves the one real production composition root — `CerneApp` resolving
218	/// `sl<AuthCubit>()`/`sl<SessionRepository>()`/`sl<VaultRepository>()`,
219	/// building the one `go_router` (Story 1.6; AD-14's vault gate), and
220	/// wrapping it with `ExpiryOverlayHost` — actually works end to end. Every
221	/// other test either stops at DI registration
222	/// (`bootstrap_integration_test.dart`) or supplies its own
223	/// `AuthCubit`/`onAuthenticated` (`auth_screen_test.dart`), so neither
224	/// exercises `main.dart`'s own wiring.
225	void main() {
226	  TestWidgetsFlutterBinding.ensureInitialized();
227	
228	  const secureStorageChannel = MethodChannel(
229	    'plugins.it_nomads.com/flutter_secure_storage',
230	  );
231	  final fakeNativeStorage = <String, String>{};
232	  late FakePathProviderPlatform fakePathProvider;
233	
234	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
235	    final args = call.arguments as Map<dynamic, dynamic>;
236	    switch (call.method) {
237	      case 'write':
238	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
239	        return null;
240	      case 'read':
241	        return fakeNativeStorage[args['key'] as String];
242	      case 'delete':
243	        fakeNativeStorage.remove(args['key'] as String);
244	        return null;
245	      case 'containsKey':
246	        return fakeNativeStorage.containsKey(args['key'] as String);
247	      default:
248	        return null;
249	    }
250	  }
251	
252	  setUp(() async {
253	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
254	        .setMockMethodCallHandler(
255	          secureStorageChannel,
256	          handleSecureStorageCall,
257	        );
258	    // Story 3.1 — `setupCoreDependencies()` now also calls
259	    // `Hive.initFlutter()` (transitively via `hive_ce_flutter`), which
260	    // asks `path_provider` for the documents directory; faked the same
261	    // way the secure-storage channel above is.
262	    fakePathProvider = FakePathProviderPlatform();
263	    PathProviderPlatform.instance = fakePathProvider;
264	
265	    await resetCoreDependencies();
266	    await setupCoreDependencies();
267	    // `setupCoreDependencies()` registers the real `VaultRepositoryImpl`
268	    // (backed by the actual `local_auth` plugin, with no platform channel
269	    // mocked here) — swapped for a fake pre-`unlocked` one so every
270	    // existing auth/session test case (which predates AD-14's vault gate)
271	    // is unaffected; a test that wants to exercise the vault gate itself
272	    // swaps this for its own locked fake.
273	    sl.unregister<VaultRepository>();
274	    sl.registerLazySingleton<VaultRepository>(
275	      () => _FakeVaultRepository(),
276	      dispose: (repository) => repository.dispose(),
277	    );
278	    // Story 2.4 — same rationale as the `VaultRepository` swap above:
279	    // `setupCoreDependencies()` also registers the real
280	    // `AccountSettingsRepositoryImpl` (backed by the real `ApiClient`/`Dio`
281	    // pipeline, no mock server here), swapped for a fake so `CerneApp`'s
282	    // boot-time `fetchBiometricEnabled()` call never reaches the network.
283	    sl.unregister<AccountSettingsRepository>();
284	    sl.registerLazySingleton<AccountSettingsRepository>(
285	      () => _FakeAccountSettingsRepository(),
286	      dispose: (repository) => repository.dispose(),
287	    );
288	    // spec-6-1 — same rationale as the two swaps above: `setupCoreDependencies()`
289	    // also registers the real `ChatCubit` (backed by the real
290	    // `ChatRepositoryImpl`/`ApiClient`/`Dio` pipeline), swapped for one backed
291	    // by `_FakeChatRepository` so reaching Home/Chat never hits the network.
292	    sl.unregister<ChatCubit>();
293	    sl.registerLazySingleton<ChatCubit>(
294	      () => ChatCubit(_FakeChatRepository(), FakeConnectivityWatcher()),
295	      dispose: (cubit) => cubit.close(),
296	    );
297	    // `ConfirmationDialog.isOpen` is a static single-overlay guard (shared
298	    // across every instance by design, Story 1.5) — reset it so one test's
299	    // unclosed dialog never leaks into the next.
300	    ConfirmationDialog.isOpen = false;
301	  });
