24	/// A scriptable fake `EntriesRepository` — same plain-fake convention
25	/// every other repository-backed cubit test in this codebase already
26	/// uses, needed here because a single test drives several distinct
27	/// `create()` calls (the initial attempt, then a `retry()`) with
28	/// different queued results.
29	class _FakeEntriesRepository implements EntriesRepository {
30	  final List<Completer<Either<Failure, Entry>>> _completers = [];
31	  int createCallCount = 0;
32	  final List<String> createdContents = [];
33	
34	  @override
35	  Future<Either<Failure, Entry>> create({
36	    required String content,
37	    required EntrySource source,
38	    int? mediaDurationSeconds,
39	  }) {
40	    createCallCount++;
41	    createdContents.add(content);
42	    final completer = Completer<Either<Failure, Entry>>();
43	    _completers.add(completer);
44	    return completer.future;
45	  }
46	
47	  void resolve(int callIndex, Either<Failure, Entry> result) {
48	    _completers[callIndex].complete(result);
49	  }
50	
51	  @override
52	  Future<Either<Failure, EntriesPage>> list({
53	    String? cursor,
54	    int limit = 20,
55	    EntrySource? source,
56	    DateTime? dateFrom,
57	    DateTime? dateTo,
58	  }) async => throw UnimplementedError('not expected to be called');
59	
60	  @override
61	  Future<Either<Failure, Entry>> getById(String id) async =>
62	      throw UnimplementedError('not expected to be called');
63	
64	  @override
65	  Future<Either<Failure, List<Entry>>> search(
66	    String query, {
67	    EntrySource? source,
68	    DateTime? dateFrom,
69	    DateTime? dateTo,
70	  }) async => throw UnimplementedError('not expected to be called');
71	}
